/**  多行文字。 */
"long_text" | 
/**  整數。 */
"integer" | 
/**  小數（指定小數位數）。 */
"decimal" | 
/**  金額。M2a 只處理數值與小數位數，幣別在 M3 處理。 */
"money" | 
/**  日期。 */
"date" | 
/**  日期時間。 */
"datetime" | 
/**  勾選。 */
"boolean" | 
/**  下拉單選。 */
"select" | 
/**  下拉多選。 */
"multi_select" | 
/**  關聯到其他資料類別的一筆資料（M2b），見 [`CreateFieldRequest::relation_entity_id`]。 */
"relation" | 
/**
 *  附件（M2b）：值為附件的 id（`attachments.id`），附件先以 `POST /api/v1/attachments` 上傳，
 *  見 [`crate::attachment`]。
 */
"file" | 
/**  公式，唯讀，由系統計算（M2c）。 */
"formula";

